import{_ as r,o as s,c as t,a5 as a}from"./chunks/framework.QWVCgkrI.js";const i="/study/images/hardware/nic-receive-queues.svg",g=JSON.parse('{"title":"NICの受信キューとRSS — フレームがアプリへ届くまで","description":"","frontmatter":{"title":"NICの受信キューとRSS — フレームがアプリへ届くまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"PCIe接続のNICが受信バッファをDMAで埋め、CPUが割り込みやポーリングで回収する経路を追う。RSSと、NIC側・UDPソケット側の取りこぼしを区別する。","aliases":["NIC","RX ring","受信リング","受信記述子","receive queue","RSS","Receive Side Scaling","NAPI","interrupt moderation","RcvbufErrors"],"verification":"LinuxカーネルとMicrosoftのドライバー資料、IETFのホスト要件、Wiresharkの公式ガイドに照合（2026-11-07）"}},"headers":[],"relativePath":"hardware/io/nic-receive-queues.md","filePath":"hardware/io/nic-receive-queues.md"}'),n={name:"hardware/io/nic-receive-queues.md"};function o(h,e,l,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="nicの受信キューとrss-—-フレームがアプリへ届くまで" tabindex="-1">NICの受信キューとRSS — フレームがアプリへ届くまで <a class="header-anchor" href="#nicの受信キューとrss-—-フレームがアプリへ届くまで" aria-label="Permalink to &quot;NICの受信キューとRSS — フレームがアプリへ届くまで&quot;">​</a></h1><p>別のPCから送られたゲームの位置更新を、PCIe接続のネットワークカード（NIC）がEthernetで受け取る例を考えます。<code>recvfrom</code>でUDPデータグラムを読み出せるようになるまでに、NICによるメモリへの転送、ドライバーによる受信処理、OSによるソケットの振り分けが行われます。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/network-interface-card-support" target="_blank" rel="noreferrer">MicrosoftのNICとDMA</a> · <a href="/study/network/udp-datagrams.html">UDPデータグラムの境界と送受信</a></p><h2 id="フレームの置き場所を先に渡す" tabindex="-1">フレームの置き場所を先に渡す <a class="header-anchor" href="#フレームの置き場所を先に渡す" aria-label="Permalink to &quot;フレームの置き場所を先に渡す&quot;">​</a></h2><ol><li><strong>ドライバーが受信バッファを用意する。</strong> ドライバーはホストメモリにバッファを用意し、NICから書き込めるようにDMAマッピングを設定します。NICに渡す**受信記述子（RX descriptor）<strong>には、バッファのDMAアドレスなどが入ります。記述子を並べ、末尾の次に先頭へ戻るよう繰り返し使うのが</strong>受信リング（RX ring）**です。</li><li><strong>NICがフレームを書き込む。</strong> フレームが届くと、NICは使用可能な記述子を参照し、対応するバッファへDMAでデータを書き込みます。ドライバーは記述子の完了フラグや、別の完了キューのエントリーから、受信した長さと状態などを確認します。完了の表し方は機種によって異なります。</li><li><strong>ドライバーがデータを回収し、受信先を補充する。</strong> ドライバーが受信データをOSのネットワークスタックへ渡し、処理済みのスロットへ再利用可能になったバッファか、別の空きバッファを補充します。通常のUDP受信では、OSが該当ソケットの受信キューへデータグラムを入れ、アプリが<code>recvfrom</code>などで取り出します。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/network-interface-card-support" target="_blank" rel="noreferrer">MicrosoftのNICとDMA</a> · <a href="https://docs.kernel.org/networking/device_drivers/ethernet/amazon/ena.html#rx" target="_blank" rel="noreferrer">LinuxのENAドライバーの受信経路</a> · <a href="/study/hardware/io/dma-and-iommu.html">DMAとIOMMU</a> · <a href="/study/hardware/io/pcie-links.html">PCI Expressのリンクとレーン</a></li></ol><figure class="study-figure"><img src="'+i+`" alt="ドライバーが記述子で受信バッファを渡し、NICがDMAでフレームを書く。OSが受信分をUDPソケットへ届け、アプリがrecvfromで読む。4スロットの受信リングの例では、0と1は回収待ち、2と3はNICが使える。末尾の次は先頭へ戻る。" width="760" height="500" loading="lazy"><figcaption>記述子が受信先を指し、フレームの中身は別の受信バッファに入ります。<a href="/study/images/hardware/nic-receive-queues.svg" target="_blank" rel="noopener noreferrer">NICの受信経路とリングの図を拡大</a></figcaption></figure><h2 id="割り込みで知らせ、ポーリングで回収する" tabindex="-1">割り込みで知らせ、ポーリングで回収する <a class="header-anchor" href="#割り込みで知らせ、ポーリングで回収する" aria-label="Permalink to &quot;割り込みで知らせ、ポーリングで回収する&quot;">​</a></h2><p><strong>割り込み</strong>はCPUに受信処理のきっかけを伝えます。PCIeの<strong>MSI-X</strong>を使う構成では、キューまたはキューの組に別々の割り込みベクターを割り当てられます。Linuxの<strong>NAPI</strong>では、典型的には割り込みを受けてドライバーのポーリング処理を予約します。ポーリング処理は、NICが完了を記録した受信データを一定件数まで回収し、まだ残っていれば再度実行されます。WindowsのNDISにも、割り込みのあとに<strong>DPC</strong>（遅延プロシージャ呼び出し）で受信処理を行う構成があります。<a href="https://docs.kernel.org/PCI/msi-howto.html" target="_blank" rel="noreferrer">LinuxのMSI/MSI-X</a> · <a href="https://docs.kernel.org/networking/napi.html" target="_blank" rel="noreferrer">LinuxのNAPI</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/rss-with-message-signaled-interrupts" target="_blank" rel="noreferrer">MicrosoftのRSSとメッセージ割り込み</a></p><p>**割り込み抑制（interrupt moderation）**を使うと、対応するNICは複数の受信完了をまとめて通知できます。割り込みの回数が減ると、CPUがパケット処理に時間を回せるため、高負荷時の処理能力が上がる場合があります。小さな更新がたまに届く場合は、通知を待つ時間が受信遅延に加わることがあります。ゲームの通信を観察するときは、平常時と負荷をかけたときで、パケット数と遅延の分布を比べます。<a href="https://learn.microsoft.com/en-us/windows-server/networking/technologies/network-subsystem/net-sub-performance-tuning-nics#interrupt-moderation" target="_blank" rel="noreferrer">Microsoftの割り込み抑制と性能</a> · <a href="/study/network/latency-throughput-and-queues.html">遅延・帯域・待ち行列</a></p><h2 id="rssは複数のフローをキューに振り分ける" tabindex="-1">RSSは複数のフローをキューに振り分ける <a class="header-anchor" href="#rssは複数のフローをキューに振り分ける" aria-label="Permalink to &quot;RSSは複数のフローをキューに振り分ける&quot;">​</a></h2><p>**RSS（Receive Side Scaling）**は、複数の論理CPUへ受信処理を分散する仕組みです。複数のハードウェア受信キューを使う構成では、NICがパケットのヘッダーの一部をハッシュ化し、結果から振り分け表を引いてキューを選びます。例えば対応するTCPフローでは、送信元・宛先のIPアドレスとポートがハッシュの入力になります。使う項目はプロトコルやNICの対応機能、設定によって異なります。<a href="https://docs.kernel.org/networking/scaling.html#rss-receive-side-scaling" target="_blank" rel="noreferrer">LinuxのRSS</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/introduction-to-receive-side-scaling" target="_blank" rel="noreferrer">MicrosoftのRSSの概要</a></p><p>振り分け設定とハッシュの入力が同じなら、同じ方向のフローのパケットは同じキューへ入ります。例えばフローAをキュー0、フローBをキュー1へ振り分けると、それぞれの受信処理を別のCPUで進められます。異なるフローが同じキューへ入ることもあり、一つのフローに受信が集中する場合は、そのキューを担当するCPUが先に忙しくなります。RSSで分散するのはOS側の受信処理です。ゲームの更新ロジックをどのスレッドで実行するかは、アプリ側で決まります。<a href="https://docs.kernel.org/networking/scaling.html#rss-receive-side-scaling" target="_blank" rel="noreferrer">LinuxのRSSとキュー・CPUの関係</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/rss-with-hardware-queuing" target="_blank" rel="noreferrer">Microsoftのハードウェア受信キュー</a></p><h2 id="取りこぼした場所を見分ける" tabindex="-1">取りこぼした場所を見分ける <a class="header-anchor" href="#取りこぼした場所を見分ける" aria-label="Permalink to &quot;取りこぼした場所を見分ける&quot;">​</a></h2><table tabindex="0"><thead><tr><th>場所</th><th>起きること</th><th>手がかり</th></tr></thead><tbody><tr><td>NIC側の受信リング</td><td>空き受信バッファの補充が到着に追いつかず、NICがフレームを受け入れられないことがある。</td><td>Linuxの<code>rx_missed_errors</code>や、ドライバーが公開するキューごとの破棄・バッファ不足のカウンターを確認する。</td></tr><tr><td>OS側のUDPソケット</td><td>NICで受信できても、アプリが読み出すより速くデータグラムがたまると、ソケットの受信キューへ追加できずに破棄されることがある。</td><td>Linuxでは<code>/proc/net/snmp</code>の<code>Udp</code>欄の<code>RcvbufErrors</code>を確認する。これはIPv4 UDPの集計で、個別のソケットを示す値ではない。</td></tr></tbody></table><p>受信リングとソケットの受信キューは、それぞれ別に容量があります。ソケットの<code>SO_RCVBUF</code>はOS側の受信バッファに関わる設定で、<code>recvfrom</code>の引数で渡すアプリのバッファは、受信したデータを一回の呼び出しで受け取る置き場所です。負荷をかける前後で各カウンターの差分を取ると、どの段階で破棄が増えたかを切り分けられます。<a href="https://docs.kernel.org/networking/statistics.html" target="_blank" rel="noreferrer">Linuxのインターフェース統計</a> · <a href="https://github.com/torvalds/linux/blob/v6.12/net/ipv4/udp.c" target="_blank" rel="noreferrer">LinuxのUDP受信処理</a> · <a href="https://github.com/torvalds/linux/blob/v6.12/net/ipv4/proc.c" target="_blank" rel="noreferrer">LinuxのUDP統計の出力</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-setsockopt" target="_blank" rel="noreferrer">Microsoftのソケットオプション</a></p><h2 id="手元でnicの設定と受信統計を確認する" tabindex="-1">手元でNICの設定と受信統計を確認する <a class="header-anchor" href="#手元でnicの設定と受信統計を確認する" aria-label="Permalink to &quot;手元でNICの設定と受信統計を確認する&quot;">​</a></h2><p>WindowsではPowerShellで有線アダプターの名前を調べ、例の<code>Ethernet</code>をその名前に置き換えます。RSS対応アダプターでは設定を表示できます。アダプターの統計はそのインターフェースの集計で、破棄の内訳の出し方はドライバーによって異なります。<a href="https://learn.microsoft.com/en-us/powershell/module/netadapter/get-netadapterrss" target="_blank" rel="noreferrer">Get-NetAdapterRss</a> · <a href="https://learn.microsoft.com/en-us/powershell/module/netadapter/get-netadapterstatistics" target="_blank" rel="noreferrer">Get-NetAdapterStatistics</a></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetAdapter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Physical </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LinkSpeed</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetAdapterRss</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Ethernet&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetAdapterStatistics</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Ethernet&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span></code></pre></div><p>Linuxでは<code>ip link show</code>で有線インターフェースを調べ、<code>enp3s0</code>をその名前に置き換えます。<code>ethtool -S</code>に出る項目はドライバーごとに異なります。<a href="https://docs.kernel.org/networking/statistics.html" target="_blank" rel="noreferrer">Linuxのインターフェース統計とethtool</a></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp3s0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ethtool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp3s0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^Udp:&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/net/snmp</span></span></code></pre></div><p>実際のNICを観察するには、別のPCから対象インターフェースのIPアドレスへ送信します。UDP受信の実践サンプルは、同じホスト内で通信するループバックの<code>127.0.0.1</code>を使います。こちらは物理NICを経由せず、ソケットの使い方を確認できます。<a href="https://www.rfc-editor.org/rfc/rfc1122.html#section-3.2.1.3" target="_blank" rel="noreferrer">IETF RFC 1122 §3.2.1.3</a> · <a href="/study/practice/network/udp-loopback-observation.html">UDP受信の実践</a></p><p>ホスト上のキャプチャで送信パケットのチェックサムが不正に見える場合は、NICが送信時に計算する前のデータを見ている可能性があります。パケットキャプチャを読むときは、どの機器の、送受信処理のどの地点で取ったデータかも確認します。<a href="https://www.wireshark.org/docs/wsug_html_chunked/ChAdvChecksums.html#ChAdvChecksumsOffload" target="_blank" rel="noreferrer">Wiresharkのチェックサムオフロード</a></p>`,21)])])}const u=r(n,[["render",o]]);export{g as __pageData,u as default};
